	while (y >= 0)
		decreases y
	{
		assert (x + y) == n;  // fails
		x := x+1;
		y := y-1;
		assert (x + y) == n;
	}
	assert (y < 0) && (x + y) == n;
}
*/

// varianta cu invariant
method Invariant1()
{
	// var n: int := *;  // havoc
	var n: int :| n >= 0;  
	var y := n;
	var x := 0;
	while (y >= 0)
		decreases y
		invariant (x + y) == n;
	{
		x := x+1;
		y := y-1;
	}
	assert (y < 0) && (x + y) == n;
}

